design_system:
:root {
  /* Typography */
  --font-display: 'Space Grotesk', ui-sans-serif, system-ui, -apple-system, 'Segoe UI', Roboto, 'Helvetica Neue', Arial, 'Noto Sans', 'Apple Color Emoji', 'Segoe UI Emoji';
  --font-text: 'Manrope', ui-sans-serif, system-ui, -apple-system, 'Segoe UI', Roboto, 'Helvetica Neue', Arial, 'Noto Sans', 'Apple Color Emoji', 'Segoe UI Emoji';
  --font-feature-tabular: 'tnum' 1;

  /* Type scale */
  --text-display-xl-size: 56px; --text-display-xl-line: 64px; --text-display-xl-weight: 700;
  --text-h1-size: 40px; --text-h1-line: 48px; --text-h1-weight: 700;
  --text-h2-size: 32px; --text-h2-line: 40px; --text-h2-weight: 700;
  --text-h3-size: 24px; --text-h3-line: 32px; --text-h3-weight: 600;
  --text-body-l-size: 18px; --text-body-l-line: 28px; --text-body-l-weight: 400;
  --text-body-m-size: 16px; --text-body-m-line: 24px; --text-body-m-weight: 400;
  --text-caption-size: 14px; --text-caption-line: 20px; --text-caption-weight: 500;
  --text-micro-size: 12px; --text-micro-line: 16px; --text-micro-weight: 500;

  /* Colors */
  --color-bg: #FFFFFF;
  --color-surface: #F7FAFC;
  --color-text: #0B1220;
  --color-text-muted: #5B667A;
  --color-border: #E5E7EB;
  --color-accent: #0F766E;
  --color-on-accent: #FFFFFF;
  --color-success: #16A34A;
  --color-warning: #B45309;
  --color-danger: #DC2626;

  /* Spacing */
  --space-1: 4px; --space-2: 8px; --space-3: 12px; --space-4: 16px; --space-5: 20px; --space-6: 24px; --space-8: 32px; --space-10: 40px; --space-12: 48px; --space-16: 64px; --space-20: 80px;

  /* Radii */
  --radius-card: 12px; --radius-button: 8px; --radius-pill: 999px;

  /* Elevation */
  --shadow-0: none;
  --shadow-1: 0 1px 2px rgba(16,24,40,0.06);
  --shadow-2: 0 4px 12px rgba(16,24,40,0.08);
  --shadow-3: 0 8px 24px rgba(16,24,40,0.12);

  /* Motion */
  --motion-fast: 150ms; --motion: 200ms; --motion-slow: 260ms;
  --ease-out: cubic-bezier(0.22, 1, 0.36, 1);
  --ease-spring: cubic-bezier(0.2, 0.8, 0.2, 1);

  /* Layout */
  --container-max-desktop: 1200px; --container-max-tablet: 720px; --grid-columns: 12; --grid-gutter: 24px; --container-pad-mobile: 16px;
}

/***** Component tokens *****/
.pricing-toggle { height: 40px; border-radius: var(--radius-pill); border: 1px solid var(--color-border); }
.pricing-toggle__option { padding: 6px 12px; border-radius: calc(var(--radius-pill) - 2px); }
.card { border: 1px solid var(--color-border); border-radius: var(--radius-card); box-shadow: var(--shadow-1); background: var(--color-bg); }
.card--recommended { box-shadow: var(--shadow-3); }
.card__toprule { height: 2px; background: var(--color-accent); }
.price { font-family: var(--font-display); font-size: var(--text-h2-size); line-height: var(--text-h2-line); font-feature-settings: var(--font-feature-tabular); }
.price--recommended { font-size: var(--text-h1-size); line-height: var(--text-h1-line); }
.button--primary { background: var(--color-accent); color: var(--color-on-accent); border-radius: var(--radius-button); height: 48px; box-shadow: var(--shadow-1); }
.button--secondary { border: 1px solid var(--color-border); color: var(--color-text); background: transparent; }
.feature-row__icon { color: var(--color-success); }
